#!/usr/bin/env bash
# One fleet run behind the machine's heavy-job lock.
#
#   spikes/pi05/fleet.sh NAME MANIFEST_KIND --rows N --workers W --policy P [fleet.py flags...]
#
# MANIFEST_KIND is one of manifests.py's kinds. Writes
# ~/.cache/robots-probes/pi05/runs/NAME/ and logs/NAME.log, and refuses to
# overwrite a run. The exit status is the fleet runner's own. Copied from
# spikes/xvla-speed/fleet.sh; the manifests are generated by this spike's copy of
# manifests.py, which gives the same episodes as the X-VLA spike's.
set -euo pipefail

name="$1"; kind="$2"; shift 2
here="$(cd "$(dirname "$0")" && pwd)"
repo="$(cd "$here/../.." && pwd)"
base="$HOME/.cache/robots-probes/pi05"
py="$base/venv/bin/python"
out="$base/runs/$name"
mkdir -p "$base/logs" "$base/runs" "$base/manifests"
if [ -e "$out" ]; then
    echo "run directory $out exists already; choose another name" >&2
    exit 2
fi
[ -e "$base/manifests/$kind.jsonl" ] || "$py" "$here/manifests.py" "$kind" "$base/manifests/$kind.jsonl"
export PYTHONUNBUFFERED=1
cd "$repo"
# Wait for memory before queueing for the heavy-job lock: other agents' light jobs share this machine.
# Needed: the policy (15.5 GiB with its GPU memory), 2.7 GiB per worker, and 8 GiB that must stay free.
workers=6
prev=""
for a in "$@"; do [ "$prev" = "--workers" ] && workers="$a"; prev="$a"; done
need=$(awk -v w="$workers" 'BEGIN { n = 15.5 + 2.7 * w; if (n < 18) n = 18; printf "%d", n + 8 + 0.5 }')
echo "# $(date '+%F %T') load $(cut -d' ' -f1-3 /proc/loadavg): fleet.py $kind $*" >"$base/logs/$name.log"
status=3
for attempt in $(seq 1 "${P5_RETRIES:-24}"); do
    until [ "$(awk '/MemAvailable/ {printf "%d", $2 / 1048576}' /proc/meminfo)" -ge "$need" ]; do
        echo "# $(date '+%T') waiting: $(awk '/MemAvailable/ {printf "%.1f", $2 / 1048576}' /proc/meminfo) GiB available, need $need" >>"$base/logs/$name.log"
        sleep 60
    done
    status=0
    tools/heavy-run "$py" "$here/fleet.py" --manifest "$base/manifests/$kind.jsonl" --out "$out" "$@" \
        </dev/null >>"$base/logs/$name.log" 2>&1 || status=$?
    [ "$status" -eq 3 ] || break
    # refused to start (not enough memory): only empty directories were made; remove them and wait
    find "$out" -depth -type d -empty -delete
    echo "# $(date '+%T') attempt $attempt refused to start; retrying in 5 minutes" >>"$base/logs/$name.log"
    sleep 300
done
grep -v "WARN\|robosuite\|macro\|Assets\|Local assets\|task orders\|Loading weights\|torch_dtype\|unauthenticated\|Warning\|warn(\|^$" \
    "$base/logs/$name.log" | tail -n "${P5_TAIL:-9}"
echo "# exit status $status"
exit $status
